installation.script:
#!/bin/bash
set -e
mkdir -p /mnt/server
cd /mnt/server

cat > package.json <<'EOF'
{
  "name": "afk-bot",
  "version": "1.0.0",
  "private": true,
  "main": "index.js",
  "dependencies": {
    "mineflayer": "^4.0.0"
  }
}
EOF

cat > index.js <<'EOF'
const mineflayer = require('mineflayer')

const env = process.env
const delay = (parseInt(env.RECONNECT_DELAY, 10) || 30) * 1000
let bot = null
let afkTimer = null
let stopping = false

function start () {
  const options = {
    host: env.MC_HOST,
    port: parseInt(env.MC_PORT, 10) || 25565,
    username: env.MC_USERNAME,
    auth: env.MC_AUTH || 'microsoft',
    profilesFolder: './auth-cache'
  }
  if (env.MC_VERSION) options.version = env.MC_VERSION

  console.log('Connecting to ' + options.host + ':' + options.port + ' ...')
  bot = mineflayer.createBot(options)

  bot.once('spawn', () => {
    console.log('Bot is online as ' + bot.username)
    if (env.ANTI_AFK === '1') {
      afkTimer = setInterval(() => bot.swingArm(), 60000)
    }
  })

  bot.on('kicked', (reason) => console.log('Kicked: ' + JSON.stringify(reason)))
  bot.on('error', (err) => console.log('Error: ' + err.message))

  bot.on('end', (reason) => {
    clearInterval(afkTimer)
    if (stopping) return
    console.log('Connection closed (' + reason + '), retrying in ' + (delay / 1000) + ' s')
    setTimeout(start, delay)
  })
}

function shutdown () {
  stopping = true
  console.log('Stopping bot')
  if (bot) bot.quit()
  setTimeout(() => process.exit(0), 500)
}

process.on('SIGINT', shutdown)
process.on('SIGTERM', shutdown)

console.log('AFK bot started')
start()
EOF

npm install --omit=dev
echo 'Installation complete'
